# ==============================================================================# 040_DASHBOARD_ENGINE.py# ==============================================================================import sqlite3from pathlib import Pathfrom datetime import datetimeROOT = Path(__file__).resolve().parentDB = ROOT / "MISSION_CONTROL" / "database" / "mission_control.db"conn = sqlite3.connect(DB, timeout=30)conn.row_factory = sqlite3.Rowcur = conn.cursor()

cur.execute("PRAGMA journal_mode=WAL")
cur.execute("PRAGMA synchronous=NORMAL")
cur.execute("PRAGMA busy_timeout=30000")print("=" * 80)print("IOTEC MISSION CONTROL DASHBOARD")print("=" * 80)print("Atualizado:", datetime.now().strftime("%d/%m/%Y %H:%M:%S"))print("=" * 80)# ------------------------------------------------------------------------------# SERVICES# ------------------------------------------------------------------------------cur.execute("SELECT COUNT(*) total FROM services")services = cur.fetchone()["total"]# ------------------------------------------------------------------------------# RUNTIME# ------------------------------------------------------------------------------cur.execute("""SELECTCOUNT(*) total,SUM(CASE WHEN status='READY' THEN 1 ELSE 0 END) readyFROM runtime""")runtime = cur.fetchone()runtime_total = runtime["total"] or 0runtime_ready = runtime["ready"] or 0# ------------------------------------------------------------------------------# SCHEDULER# ------------------------------------------------------------------------------cur.execute("SELECT COUNT(*) total FROM scheduler")scheduler = cur.fetchone()["total"]# ------------------------------------------------------------------------------# JOBS# ------------------------------------------------------------------------------cur.execute("SELECT COUNT(*) total FROM job_history")jobs = cur.fetchone()["total"]# ------------------------------------------------------------------------------# TASKS# ------------------------------------------------------------------------------cur.execute("""SELECTCOUNT(*) total,SUM(CASE WHEN status='COMPLETED' THEN 1 ELSE 0 END) completedFROM task_queue""")tasks = cur.fetchone()task_total = tasks["total"] or 0task_completed = tasks["completed"] or 0# ------------------------------------------------------------------------------# WORKFLOWS# ------------------------------------------------------------------------------cur.execute("""SELECTCOUNT(*) total,SUM(CASE WHEN status='COMPLETED' THEN 1 ELSE 0 END) completedFROM workflows""")wf = cur.fetchone()workflow_total = wf["total"] or 0workflow_completed = wf["completed"] or 0# ------------------------------------------------------------------------------# PLUGINS# ------------------------------------------------------------------------------cur.execute("""SELECTCOUNT(*) total,SUM(CASE WHEN status='ONLINE' THEN 1 ELSE 0 END) onlineFROM plugins""")plugins = cur.fetchone()plugin_total = plugins["total"] or 0plugin_online = plugins["online"] or 0# ------------------------------------------------------------------------------# HEALTH# ------------------------------------------------------------------------------cur.execute("""SELECT healthFROM runtime_monitorORDER BY id DESCLIMIT 1""")row = cur.fetchone()health = row["health"] if row else 0# ------------------------------------------------------------------------------# METRICS# ------------------------------------------------------------------------------cur.execute("""SELECT COUNT(*) totalFROM metrics""")metrics = cur.fetchone()["total"]# ------------------------------------------------------------------------------# DISPLAY# ------------------------------------------------------------------------------print(f"SERVICES..............: {services}")print(f"RUNTIME READY.........: {runtime_ready}/{runtime_total}")print(f"SCHEDULER TASKS.......: {scheduler}")print(f"JOBS EXECUTADOS.......: {jobs}")print(f"TASKS COMPLETADAS.....: {task_completed}/{task_total}")print(f"WORKFLOWS.............: {workflow_completed}/{workflow_total}")print(f"PLUGINS ONLINE........: {plugin_online}/{plugin_total}")print(f"HEALTH................: {health:.2f}%")print(f"METRICS REGISTRADAS...: {metrics}")print("=" * 80)if health >= 95:    status = "MISSION CONTROL ONLINE"elif health >= 80:    status = "MISSION CONTROL DEGRADED"else:    status = "MISSION CONTROL CRITICAL"print("STATUS:", status)print("=" * 80)conn.close()

